# Code generated by Claude
"""Generic episode runner: it knows nothing about any particular task.

It does what a policy must not do itself: reset the scene, check success, enforce the timeouts, save the log and the summary. Everything else
is the policy's (src/sequential_policy.py and the stages) or the controller's (src/control_loop.py). A task supplies the rest as a dictionary:

    summary = run_episode(task, model, data, mode="auto", viewer=None, out_dir=None, handoff_frame=None, held=None, loop_cfg=None,
                          record_dir=None, extra_sources=None)

The task dictionary (the beaker task's is built by src/task_beaker_hotplate.make_task()):
    "name" (str)                        the task's name.
    "reset"(model, data) -> dict        resets the simulation state and places the task's objects; returns where the robot spawns:
                                        {"spawn_pos": [x, y, z] in metres, "spawn_yaw": radians}.
    "make_policy"(model, data) -> src  builds the policy command source (a sequential policy, see src/sequential_policy.py); used in "auto" mode.
    "check_success"(model, data) -> (bool, diagnostics)
    "limits" (dict)                     "timeout_after_handoff" and "operator_timeout" (seconds), "log_hz" (hertz), "exclusive" (bool).
    "log_extras"(model) -> (names, row_fn)   optional: extra log columns, row_fn(data) -> list of formatted values.
    "view_points"(model, data) -> dict       optional: the world points the fixed eagle camera must see (not used by the runner itself).
    "handoff_camera" (str)              optional: the camera whose picture is saved at the handoff. Default "eagle_cam".
    "handoff_label" (str)               optional: the phase label that marks the handoff in a recording (used by replay). Default "DONE".
    "recipe" (dict)                     {"entry": "module:function", "cfg": {...}}: how replay rebuilds the model of a recording; see src/replay.py.
    "meta" (dict)                       optional: configuration saved in the recording.

  reset     task["reset"]; the loop spawns the robot at the returned pose and settles it (nothing is randomized). The same model / data can be
            used for any number of episodes.
  mode      "auto": ONE policy (task["make_policy"]) owns the whole task. It may ask for operator control (the controller then switches to
            teleop at once). In the viewer F9 takes over from the policy, Enter hands control back (the policy continues its stage), Delete
            aborts (ABORTED_BY_OPERATOR); the last two only act while the operator has control.
            "teleop": no policy; the operator (keyboard) drives from the start and time 0 counts as the handoff.
  handoff   the moment the policy's status says "handoff" (a policy without that key: the first tick; teleop start: the first tick). In "auto"
            mode the handoff camera's frame at that moment is saved to `handoff_frame` (if given); a teleop-start episode saves none.
  judge     task["check_success"] every tick after the handoff, whoever is in charge: success ends the episode (SUCCESS, with operator_assisted
            true if the operator had control at any time). TIMEOUT: limits["timeout_after_handoff"] of sim time under AUTO control (paused
            while the operator has control), or limits["operator_timeout"] under OPERATOR control (OPERATOR_NO_RESPONSE instead of TIMEOUT if
            the policy had requested the operator and no key was pressed at all). If the policy reports an error the episode ends at once
            with the outcome name the failing stage supplied ("failure_outcome" in the policy status, "POLICY_FAILED" by default; the beaker
            task's staging stage supplies STAGING_FAILED).
  log       out_dir/episode_log.csv (state, mode and applied commands at limits["log_hz"]) and out_dir/episode_summary.json.
Exclusivity (one subsystem moves at a time) follows limits["exclusive"]; the loop's default stays off elsewhere. `extra_sources` (test only):
a factory make(model, data) -> {name: source} of additional sources, e.g. the kick source of the correction test.

The runner drives src/control_loop.run_loop through its cfg["on_tick"] hook (success, timeouts, contacts, the log). The summary: outcome,
the policy's report (for the beaker task the staging stage's own: phase durations, arrival errors, pose corrections, drift, clearance, pose error
at the handoff, at the top level, and every stage's report under "stages"), contacts per phase (phase "OPERATOR" while the operator
has control), the mode switches, operator_time_s, the holds the loop logged, and the success-check diagnostics.
"""

import csv
import json
import math
import time
from pathlib import Path

import cv2
import glfw
import numpy as np

from src import robot_specs
from src.control_loop import run_loop
from src.keyboard_source import DRIVE_CFG, make_keyboard_source
from src.robot_helpers import arm_ids, make_contact_monitor

TICK_HZ = 150           # the command tick: physics_hz / TICK_HZ = 5 physics steps (the window is redrawn every 5th tick, 30 Hz) [row M127 PENDING David: no decision recorded]


def run_episode(task, model, data, mode="auto", viewer=None, out_dir=None, handoff_frame=None, held=None, loop_cfg=None, record_dir=None,
                extra_sources=None, face=None, stop_after_handoff_s=None):
    """Runs one episode of a task and returns its summary.

    Resets the scene, builds the sources (the policy in "auto" mode, the keyboard source, and any extra sources), runs the control loop
    (src/control_loop.run_loop) with an on-tick hook that judges success, enforces the timeouts, counts contacts and writes the log, then builds
    the summary. See the module docstring for the task dictionary and the rules of the episode.

    Units are seconds (s), metres (m), radians (rad), newtons (N) and hertz (Hz).

    The log, if `out_dir` is given, is out_dir/episode_log.csv: one row at the first tick of every 1/log_hz seconds of simulation time, with the
    columns sim_time (s), phase (the policy's phase, or "OPERATOR" while the operator has control), mode ("auto" or "teleop"), base_x and
    base_y (m), base_yaw_deg, pedestal_m, <side>_joint1..7 (rad) and <side>_finger1..2 (m) for both arms, the task's extra columns (the beaker task: beaker_x, beaker_y, beaker_z in metres), then the applied commands: cmd_twist_lin
    (m/s), cmd_twist_ang (rad/s), cmd_pedestal (m), cmd_<side>_joint1..7 (rad) and cmd_<side>_gripper (m) for both arms, and for both arms cmd_<side>_grip_max_force_N (newtons) and <side>_finger_force_N (the mean absolute finger actuator force,
    newtons).

    Args:
        task (dict): The task, see the module docstring.
        model (mujoco.MjModel): The compiled task model. It can be reused for any number of episodes.
        data (mujoco.MjData): The simulation data; reset at the start by the task.
        mode (str): "auto" (the task's policy runs the task, and the operator can take over) or "teleop" (the operator drives from the
            start, and time 0 is the handoff). Defaults to "auto".
        viewer (dict or None): The window viewer made by src/glfw_viewer.make_glfw_viewer, or None to run without a window. Defaults to
            None.
        out_dir (str or pathlib.Path or None): Directory for episode_log.csv and episode_summary.json; created if needed. None writes
            neither. Defaults to None.
        handoff_frame (str or pathlib.Path or None): Path of the Portable Network Graphics (PNG) file to which the handoff camera's frame
            is saved at the handoff ("auto" mode only). Defaults to None, which saves nothing.
        held (callable or None): held(key code) -> bool, telling whether a key is down (used for scripted or test key presses).
            Defaults to None, which reports no keys to the keyboard source (the loop itself reads the viewer's keys for the
            hotkeys).
        loop_cfg (dict or None): Entries that override the control loop's configuration after the runner has set its own. Defaults to None.
        record_dir (str or pathlib.Path or None): Directory in which to record the run for exact replay (src/run_record.py,
            src/replay.py); the labels are the policy's phases. Defaults to None, which records nothing.
        extra_sources (callable or None): Test only. A factory make(model, data) -> {name: source} of additional sources. Defaults to
            None.
        face (src.face.Face or None): The robot's face (RobotSimulator.face). It shows the neutral image from the start and switches to the smile when the success
            check passes. Defaults to None (no face is driven).
        stop_after_handoff_s (float or None): End the episode this many seconds after the handoff with the outcome "STAGING_COMPLETE" (the staging is the whole
            point of the run), unless it has ended already. Defaults to None (the episode runs until success, a timeout or a failure).

    Returns:
        dict: The summary, also written to episode_summary.json when `out_dir` is given. Keys:
            "outcome" (str): "SUCCESS" (the episode runs on for limits["success_linger_s"] after it, then stops), "STAGING_COMPLETE" (stop_after_handoff_s), "TIMEOUT", "OPERATOR_NO_RESPONSE", the failing stage's outcome name (for the beaker task
                "STAGING_FAILED"; "POLICY_FAILED" if the stage names none), "ABORTED_BY_OPERATOR", "ABORTED" (the loop ended with no
                stop reason, for example the viewer's quit key), or any other stop reason of the loop in capitals.
            "timeout_kind" (str or None): "auto" or "operator" for the timeouts, else None.
            "mode_at_start" (str): `mode`.
            "sim_time_end" (float): Simulation time at the end, in seconds.
            "handoff_time" (float or None): Simulation time of the handoff, in seconds; None if it never happened.
            "time_after_handoff_to_end" (float or None): sim_time_end minus handoff_time, in seconds.
            "auto_time_after_handoff_s" (float): Seconds after the handoff under automatic control.
            "operator_time_s" (float): Seconds after the handoff under operator control.
            "operator_assisted" (bool): True if the outcome is SUCCESS and the operator had control at some time.
            "mode_switches" (list): The control loop's mode log, one dict per switch: {tick, time, from, to, cause, reason, stage}.
            The policy's report (only in "auto" mode), from its report(): the keys of the stages that report at the top level (for the
                beaker task the staging stage's "staging_error", "phase_durations_s", "phase_times", "arrival_at_end_of_drive",
                "base_pose_error_at_handoff", "first_turn_deg", "final_in_place_turn_deg", "planned_final_turn_deg", "drive_reapproaches",
                "pose_corrections", "base_drift", and "min_base_to_bench_clearance_during_drive_mm"; see
                make_staging_source()), and "stages" (dict): stage name -> that stage's report.
            "contacts_by_phase" (dict): Phase name (or "OPERATOR") -> list of {"pair": [name, name], "first_s": float,
                "last_s": float, "ticks": int} for each distinct robot contact pair seen in that phase.
            "holds" (list): The control loop's hold log (exclusivity waits).
            "success_check" (dict or None): The diagnostics of the last success check; None if no check ran.
            "log_rows_hz" (float): The log rate, hertz.
            "wall_seconds" (float): Wall-clock seconds the episode took.

    Raises:
        ValueError: If `mode` is neither "auto" nor "teleop".
    """
    wall0 = time.perf_counter()
    if mode not in ("auto", "teleop"):
        raise ValueError(f"mode must be 'auto' or 'teleop', not {mode!r}")
    lim = task["limits"]
    spawn = task["reset"](model, data)
    if face is not None:
        face.set_smile(False)
    linger = float(lim.get("success_linger_s", 0.0))          # after a success the episode runs on this long (the smile shows), then stops

    physics_hz = 1.0 / model.opt.timestep
    spf = max(1, round(physics_hz / TICK_HZ))
    tick_dt = spf * model.opt.timestep
    held_fn = held or (lambda code: False)
    ped = model.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id
    sources, policy = {}, None
    if mode == "auto":
        policy = task["make_policy"](model, data)
        sources["policy"] = policy
    sources["keyboard"] = make_keyboard_source(model, held_fn, DRIVE_CFG, robot_specs.PEDESTAL_SPECS["jog_speed"] * tick_dt,
                                               tuple(model.actuator_ctrlrange[ped]))
    sources.update(extra_sources(model, data) if extra_sources else {})

    contacts_now = make_contact_monitor(model)
    sides = ("left", "right")
    arm_act = {s: arm_ids(model, s) for s in sides}
    finger_qadr = [int(model.jnt_qposadr[j]) for s in sides for j in arm_act[s]["finger_jnt"]]
    extra_names, extra_row = task["log_extras"](model) if "log_extras" in task else ([], None)

    # --- bookkeeping ---
    R = {"outcome": None, "handoff_time": None, "success_time": None, "contacts": {}, "diag": None, "t_end": None, "timeout_kind": None,
         "auto_ticks": 0, "operator_ticks": 0}
    log_file, log_csv, next_log = None, None, [0.0]
    if out_dir is not None:
        Path(out_dir).mkdir(parents=True, exist_ok=True)
        log_file = open(Path(out_dir) / "episode_log.csv", "w", newline="")
        log_csv = csv.writer(log_file)
        log_csv.writerow(["sim_time", "phase", "mode", "base_x", "base_y", "base_yaw_deg", "pedestal_m"]
                         + [f"{s}_joint{i}" for s in sides for i in range(1, 8)] + [f"{s}_finger{k}" for s in sides for k in (1, 2)]
                         + list(extra_names)
                         + ["cmd_twist_lin", "cmd_twist_ang", "cmd_pedestal"]
                         + [c for s in sides for c in [f"cmd_{s}_joint{i}" for i in range(1, 8)] + [f"cmd_{s}_gripper"]]
                         + [c for s in sides for c in (f"cmd_{s}_grip_max_force_N", f"{s}_finger_force_N")])

    def on_tick(obs, loop):
        """Judges one tick: handoff, contacts, the log row, success, timeouts and failure; returns the status text for the viewer.

        Args:
            obs (dict): The loop's observation (with "policy" status, "mode" and "operator").
            loop (dict): The loop's hook API (stop, render, ...).

        Returns:
            str: The phase, the seconds since the handoff, the operator time and the outcome, for the viewer's status row.
        """
        t = obs["time"]
        ps = obs.get("policy")                                    # the policy's status (None in a teleop-start episode)
        cur = obs["mode"]
        phase = "OPERATOR" if cur == "teleop" else ps["phase"]
        x, y, yaw = obs["base_pose"]
        if R["handoff_time"] is None and (ps is None or ps.get("handoff", True)):
            R["handoff_time"] = t
            if policy is not None and handoff_frame is not None:
                Path(handoff_frame).parent.mkdir(parents=True, exist_ok=True)
                cv2.imwrite(str(handoff_frame), cv2.cvtColor(loop["render"](task.get("handoff_camera", "eagle_cam")), cv2.COLOR_RGB2BGR))
            print(f"[episode] t={t:.2f} s: " + ("HANDOFF reached; the policy's next stage is in charge"
                                                 if policy is not None else "teleop start: the operator is in charge from the beginning"))
        for pair in contacts_now(data):
            c = R["contacts"].setdefault(phase, {}).setdefault(pair, {"first": t, "last": t, "ticks": 0})
            c["last"], c["ticks"] = t, c["ticks"] + 1
        # log at log_hz
        if log_csv is not None and t >= next_log[0] - 1e-9:
            next_log[0] = (math.floor(t * lim["log_hz"] + 1e-9) + 1) / lim["log_hz"]
            ap = obs["applied"]
            q = obs["joint_angles"]
            log_csv.writerow([f"{t:.4f}", phase, cur, f"{x:.9f}", f"{y:.9f}", f"{math.degrees(yaw):.9f}", f"{obs['pedestal_height']:.9f}"]
                             + [f"{q[a]:.9f}" for s in sides for a in arm_act[s]["qadr"]] + [f"{q[a]:.9f}" for a in finger_qadr]
                             + (extra_row(data) if extra_row else [])
                             + [f"{ap['twist'][0]:.9f}", f"{ap['twist'][1]:.9f}", f"{ap['pedestal']:.9f}"]
                             + [v for s in sides for v in [f"{v:.9f}" for v in ap["arm_targets"][s]] + [f"{ap['gripper'][s]:.9f}"]]
                             + [v for s in sides for v in (f"{ap['gripper_force'][s]:.9f}",
                                                           f"{abs(float(data.actuator_force[arm_act[s]['gripper']])) / robot_specs.ARM_ACTUATOR_SPECS['fingers']['fingers_per_actuator']:.9f}")])
        # end conditions
        auto_t, op_t = R["auto_ticks"] * tick_dt, R["operator_ticks"] * tick_dt
        if ps is not None and ps.get("error"):
            R["outcome"], R["t_end"] = ps.get("failure_outcome", "POLICY_FAILED"), t
            loop["stop"](R["outcome"].lower())
        elif R["handoff_time"] is not None:
            if R["success_time"] is None:
                ok, diag = task["check_success"](model, data)
                R["diag"] = diag
                if ok:
                    R["outcome"], R["success_time"] = "SUCCESS", t
                    if face is not None:
                        face.set_smile(True)
            if R["success_time"] is not None:
                if t >= R["success_time"] + linger - 1e-6:
                    R["t_end"] = t
                    loop["stop"]("success")
            elif stop_after_handoff_s is not None and t >= R["handoff_time"] + stop_after_handoff_s - 1e-6:
                R["outcome"], R["t_end"] = "STAGING_COMPLETE", t
                loop["stop"]("staging_complete")
            elif cur == "auto" and auto_t >= lim["timeout_after_handoff"] - 1e-6:
                R["outcome"], R["t_end"], R["timeout_kind"] = "TIMEOUT", t, "auto"
                loop["stop"]("timeout")
            elif cur == "teleop" and op_t >= lim["operator_timeout"] - 1e-6:
                if obs["operator"]["requested"] and not obs["operator"]["responded"]:      # the policy asked and nobody did anything
                    R["outcome"], R["t_end"], R["timeout_kind"] = "OPERATOR_NO_RESPONSE", t, "operator"
                    loop["stop"]("operator_no_response")
                else:
                    R["outcome"], R["t_end"], R["timeout_kind"] = "TIMEOUT", t, "operator"
                    loop["stop"]("timeout")
        if R["handoff_time"] is not None and R["outcome"] is None:   # the clocks: auto time is paused while the operator has control
            R["auto_ticks" if cur == "auto" else "operator_ticks"] += 1
        return (f"{phase}" + (f"  (+{auto_t:.0f} s)" if R["handoff_time"] is not None else "") + (f"  operator {op_t:.0f} s" if op_t else "")
                + (f"  {R['outcome']}" if R["outcome"] else ""))

    cfg = {"source_hz": physics_hz / spf, "spawn_pos": spawn["spawn_pos"], "spawn_yaw": spawn["spawn_yaw"], "exclusive": lim["exclusive"],
           "on_tick": on_tick, "mode": mode, "auto_source": "policy" if policy is not None else None,
           "cameras": False, "camera_roundrobin": True, "held": held,
           "hotkeys": {"take_over": glfw.KEY_F9, "hand_back": (glfw.KEY_ENTER, glfw.KEY_KP_ENTER), "abort": glfw.KEY_DELETE,
                       **({"quit": glfw.KEY_ESCAPE} if viewer is not None else {})}}
    if record_dir is not None:      # src/run_record.py: replayable with src/replay.py (labels = the phases)
        cfg.update(record_run=str(record_dir),
                   record_meta={"model": task["recipe"], "mode": mode, "handoff_label": task.get("handoff_label", "DONE"),
                                "task": {"name": task["name"], "limits": lim, **task.get("meta", {})}})
    cfg.update(loop_cfg or {})
    result = run_loop(model, data, sources, cfg, viewer=viewer)
    if log_file is not None:
        log_file.close()
    if R["outcome"] is None:
        R["outcome"], R["t_end"] = ("ABORTED" if result["stopped_by"] is None else result["stopped_by"].upper()), data.time
    elif R["t_end"] is None:                                  # a success whose lingering time was cut short (the window was closed)
        R["t_end"] = data.time

    # --- the summary ---
    summary = {
        "outcome": R["outcome"], "timeout_kind": R["timeout_kind"], "mode_at_start": mode, "sim_time_end": R["t_end"], "handoff_time": R["handoff_time"],
        "time_after_handoff_to_end": None if R["handoff_time"] is None else R["t_end"] - R["handoff_time"],
        "auto_time_after_handoff_s": R["auto_ticks"] * tick_dt, "operator_time_s": R["operator_ticks"] * tick_dt,
        "operator_assisted": R["operator_ticks"] > 0 and R["outcome"] == "SUCCESS", "mode_switches": result["mode_log"],
        **(policy["report"]() if policy is not None else {}),
        "contacts_by_phase": {k: [{"pair": list(p), "first_s": v["first"], "last_s": v["last"], "ticks": v["ticks"]} for p, v in d.items()]
                              for k, d in R["contacts"].items()},
        "holds": result["hold_log"], "success_check": R["diag"], "log_rows_hz": lim["log_hz"],
        "wall_seconds": time.perf_counter() - wall0,
    }
    if out_dir is not None:
        (Path(out_dir) / "episode_summary.json").write_text(json.dumps(summary, indent=2, default=lambda o: o.tolist() if hasattr(o, "tolist") else str(o)))
    return summary
